public void initialiseLayers(){
	LayerTiledOverlay.initialiseLayers(LayerStone::new);
	LayerTiledOverlay.initialiseLayers(LayerFrost::new);
	LayerTiledOverlay.initialiseLayers(LayerMindControl::new);
