public EntityMagicSlime(World world, EntityLivingBase caster, EntityLivingBase target, int lifetime){
	super(world);
	this.setPosition(target.posX, target.posY, target.posZ);
	this.startRiding(target);
	if (caster != null) this.setOwnerId(caster.getUniqueID());
	this.setSlimeSize(2, false); // Needs to be called before setting the experience value to 0
	this.experienceValue = 0;
	this.lifetime = lifetime;
}

public void onUpdate(){

	super.onUpdate();
	// Undoes the despawning on peaceful behaviour. I don't think there's anything in super.onUpdate that sets
	// isDead other than that, but it's better to do a quick sanity check just to be sure.
	if(this.isDead && world.getDifficulty() == EnumDifficulty.PEACEFUL && this.getHealth() > 0) this.isDead = false;
	// Bursts instantly rather than doing the falling over animation.
	if(this.getHealth() <= 0) this.setDead();

	this.updateDelegate();

	// Damages and slows the slime's victim or makes the slime explode if the victim is dead.
	if(this.getRidingEntity() != null && this.getRidingEntity() instanceof EntityLivingBase
			&& ((EntityLivingBase)this.getRidingEntity()).getHealth() > 0){
		if(this.ticksExisted % 16 == 1){
			this.getRidingEntity().attackEntityFrom(DamageSource.MAGIC, 1);
			if(this.getRidingEntity() != null && !this.world.isRemote){ // Some mobs force-dismount when attacked (normally when dying)
				((EntityLivingBase)this.getRidingEntity())
						.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, 20, 2));
			}
			this.playSound(WizardrySounds.ENTITY_MAGIC_SLIME_ATTACK, 1.0f, 1.0f);
			this.squishAmount = 0.5F;
		}
	}else{
		this.setDead();
	}
}

public void setDead(){
	// Restores behaviour from Entity, replacing slime splitting behaviour.
	this.isDead = true;
	// Makes sure that the undoing in onUpdate won't undo this. For some reason, EntitySlime sets isDead directly
	// to do the peaceful despawning, which seems odd but is actually rather handy!
	this.setHealth(0);
	// Bursting effect
	for(int i = 0; i < 30; i++){
		double x = this.posX - 0.5 + rand.nextDouble();
		double y = this.posY - 0.5 + rand.nextDouble();
		double z = this.posZ - 0.5 + rand.nextDouble();
		this.world.spawnParticle(EnumParticleTypes.SLIME, x, y, z, (x - this.posX) * 2, (y - this.posY) * 2,
				(z - this.posZ) * 2);
	}
	this.playSound(WizardrySounds.ENTITY_MAGIC_SLIME_SPLAT, 2.5f, 0.6f);
	this.playSound(WizardrySounds.ENTITY_MAGIC_SLIME_EXPLODE, 1.0f, 0.5f);
}

public boolean attackEntityFrom(DamageSource source, float amount){
	// Immune to suffocation
	return source == DamageSource.IN_WALL ? false : super.attackEntityFrom(source, amount);
}

default void updateDelegate(){

	if(!(this instanceof Entity))
		throw new ClassCastException("Implementations of ISummonedCreature must extend SoundLoopSpellEntity!");

	Entity thisEntity = ((Entity)this);

	if(thisEntity.ticksExisted == 1){
		this.onSpawn();
	}

	// For some reason Minecraft reads the entity from NBT just after the entity is created, so setting -1 as a
	// default lifetime doesn't work. The easiest way around this is to use 0 - nobody's going to need it!
	if(thisEntity.ticksExisted > this.getLifetime() && this.getLifetime() > 0){
		this.onDespawn();
		thisEntity.setDead();
	}

	if(this.hasParticleEffect() && thisEntity.world.isRemote && thisEntity.world.rand.nextInt(8) == 0)
		ParticleBuilder.create(Type.DARK_MAGIC)
		.pos(thisEntity.posX, thisEntity.posY + thisEntity.world.rand.nextDouble() * 1.5, thisEntity.posZ)
		.clr(0.1f, 0.0f, 0.0f)
		.spawn(thisEntity.world);

}

protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

	if(EntityUtils.isLiving(target)){

		if(MagicDamage.isEntityImmune(DamageType.RADIANT, target)){
			if(!world.isRemote && ticksInUse == 1 && caster instanceof EntityPlayer) ((EntityPlayer)caster)
			.sendStatusMessage(new TextComponentTranslation("spell.resist", target.getName(),
					this.getNameForTranslationFormatted()), true);
		}else if (ticksInUse % 10 == 0) {

			float damage = getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY);
			// Fire
			if(((EntityLivingBase)target).isEntityUndead()){
				damage *= getProperty(UNDEAD_DAMAGE_MULTIPLIER).floatValue();
			}
			// Damage
			EntityUtils.attackEntityWithoutKnockback(target,
					MagicDamage.causeDirectMagicDamage(caster, DamageType.RADIANT), damage);
			// Blindness
			if(!world.isRemote){
				((EntityLivingBase)target).addPotionEffect(new PotionEffect(MobEffects.BLINDNESS,
						(int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade))));
			}
		}
	}

	return true;
}

protected boolean onMiss(World world, EntityLivingBase caster, Vec3d origin, Vec3d direction, int ticksInUse, SpellModifiers modifiers){
	return true;
}

protected void spawnParticleRay(World world, Vec3d origin, Vec3d direction, EntityLivingBase caster, double distance){

	if(caster != null){
		ParticleBuilder.create(Type.BEAM).entity(caster).pos(origin.subtract(caster.getPositionVector()))
				.length(distance).clr(1, 0.6f + 0.3f * world.rand.nextFloat(), 0.2f)
				.scale(MathHelper.sin(caster.ticksExisted * 0.2f) * 0.1f + 1.4f).spawn(world);
	}else{
		ParticleBuilder.create(Type.BEAM).pos(origin).target(origin.add(direction.scale(distance)))
				.clr(1, 0.6f + 0.3f * world.rand.nextFloat(), 0.2f)
				.scale(MathHelper.sin(Wizardry.proxy.getThePlayer().ticksExisted * 0.2f) * 0.1f + 1.4f).spawn(world);
	}
}

public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	Vec3d look = caster.getLookVec();
	Vec3d origin = new Vec3d(caster.posX, caster.posY + caster.getEyeHeight() - Y_OFFSET, caster.posZ);
	if(!this.isContinuous && world.isRemote && !Wizardry.proxy.isFirstPerson(caster)){
		origin = origin.add(look.scale(1.2));
	}

	if(!shootSpell(world, origin, look, caster, ticksInUse, modifiers)) return false;

	if(casterSwingsArm(world, caster, hand, ticksInUse, modifiers)) caster.swingArm(hand);
	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

protected boolean shootSpell(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, int ticksInUse, SpellModifiers modifiers){

	double range = getRange(world, origin, direction, caster, ticksInUse, modifiers);
	Vec3d endpoint = origin.add(direction.scale(range));

	// Change the filter depending on whether living entities are ignored or not
	RayTraceResult rayTrace = RayTracer.rayTrace(world, origin, endpoint, aimAssist, hitLiquids,
			ignoreUncollidables, false, Entity.class, ignoreLivingEntities ? EntityUtils::isLiving
			: RayTracer.ignoreEntityFilter(caster));

	boolean flag = false;

	if(rayTrace != null){
		// Doesn't matter which way round these are, they're mutually exclusive
		if(rayTrace.typeOfHit == RayTraceResult.Type.ENTITY){
			// Do whatever the spell does when it hits an entity
			// FIXME: Some spells (e.g. lightning web) seem to not render when aimed at item frames
			flag = onEntityHit(world, rayTrace.entityHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// If the spell succeeded, clip the particles to the correct distance so they don't go through the entity
			if(flag) range = origin.distanceTo(rayTrace.hitVec);

		}else if(rayTrace.typeOfHit == RayTraceResult.Type.BLOCK){
			// Do whatever the spell does when it hits an block
			flag = onBlockHit(world, rayTrace.getBlockPos(), rayTrace.sideHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// Clip the particles to the correct distance so they don't go through the block
			// Unlike with entities, this is done regardless of whether the spell succeeded, since no spells go
			// through blocks (and in fact, even the ray tracer itself doesn't do that)
			range = origin.distanceTo(rayTrace.hitVec);
		}
	}

	// If flag is false, either the spell missed or the relevant entity/block hit method returned false
	if(!flag && !onMiss(world, caster, origin, direction, ticksInUse, modifiers)) return false;

	// Particle spawning
	if(world.isRemote){
		spawnParticleRay(world, origin, direction, caster, range);
	}

	return true;
}

public static boolean isEntityImmune(DamageType type, Entity entity){

	if(type == DamageType.FIRE && entity.isImmuneToFire()) return true;
	EnumSet immunities = immunityMapping.get(entity.getClass());

	return immunities != null && immunities.contains(type);
}

public static boolean attackEntityWithoutKnockback(Entity entity, DamageSource source, float amount){
	double vx = entity.motionX;
	double vy = entity.motionY;
	double vz = entity.motionZ;
	boolean succeeded = entity.attackEntityFrom(source, amount);
	entity.motionX = vx;
	entity.motionY = vy;
	entity.motionZ = vz;
	return succeeded;
}

public static void spawnEmbers(World world, EntityLivingBase caster, Entity target, int count){

	target.extinguish();

	if(world.isRemote){ // FIXME: Various syncing issues here!
		// Set NBT client-side, it's only for rendering
		// Normally dying entities are ignored but we're fiddling with them here so double-check
		if(!target.getEntityData().hasKey(NBT_KEY)){
			target.getEntityData().setInteger(NBT_KEY, target.ticksExisted);
		}
	}else{
		for(int i = 0; i < count; i++){
			EntityEmber ember = new EntityEmber(world, caster);
			double x = (world.rand.nextDouble() - 0.5) * target.width;
			double y = world.rand.nextDouble() * target.height;
			double z = (world.rand.nextDouble() - 0.5) * target.width;
			ember.setPosition(target.posX + x, target.posY + y, target.posZ + z);
			ember.ticksExisted = world.rand.nextInt(20);
			float speed = 0.2f;
			ember.motionX = x * speed;
			ember.motionY = y * 0.5f * speed;
			ember.motionZ = z * speed;
			world.spawnEntity(ember);
		}
	}
}

public void onUpdate(){

	super.onUpdate();

	if(this.collidedVertically){
		this.motionY += this.getGravityVelocity();
		this.motionX *= 0.5;
		this.motionZ *= 0.5;
	}

	world.getEntitiesInAABBexcluding(thrower, this.getEntityBoundingBox(), e -> e instanceof EntityLivingBase)
			.stream().filter(e -> !(e instanceof EntityLivingBase) || ((EntityLivingBase)e).getHealth() > 0)
			.forEach(e -> e.setFire(Spells.disintegration.getProperty(Spell.BURN_DURATION).intValue()));

	// Copied from ParticleLava
	if(this.rand.nextFloat() > (float)this.ticksExisted / this.getLifetime()){
		this.world.spawnParticle(EnumParticleTypes.SMOKE_NORMAL, this.posX, this.posY, this.posZ, this.motionX, this.motionY, this.motionZ);
	}
}

	protected void onImpact(RayTraceResult result){

//		if(result.entityHit != null){
//			result.entityHit.setFire(Spells.disintegration.getProperty(Spell.BURN_DURATION).intValue());
//		}

		if(result.typeOfHit == RayTraceResult.Type.BLOCK){
			this.inGround = true;
			this.collided = true;
			if(result.sideHit.getAxis() == EnumFacing.Axis.X) motionX = 0;
			if(result.sideHit.getAxis() == EnumFacing.Axis.Y){
				motionY = 0;
				this.collidedVertically = true;
			}
			if(result.sideHit.getAxis() == EnumFacing.Axis.Z) motionZ = 0;
		}
	}

public void applyEntityCollision(Entity entity){

	super.applyEntityCollision(entity);

	if(entity instanceof EntityLivingBase && ((EntityLivingBase)entity).getHealth() > 0){
		entity.setFire(Spells.disintegration.getProperty(Spell.BURN_DURATION).intValue());
	}
}

public int getLifetime(){
	return Spells.disintegration.getProperty(Disintegration.EMBER_LIFETIME).intValue() + extraLifetime;
}

public void onUpdate(){

	super.onUpdate();

	if(getLifetime() >=0 && this.ticksExisted > getLifetime()){
		this.setDead();
	}

	// Seeking
	if(getSeekingStrength() > 0){

		Vec3d velocity = new Vec3d(motionX, motionY, motionZ);

		RayTraceResult hit = RayTracer.rayTrace(world, this.getPositionVector(),
				this.getPositionVector().add(velocity.scale(SEEKING_TIME)), getSeekingStrength(), false,
				true, false, EntityLivingBase.class, RayTracer.ignoreEntityFilter(null));

		if(hit != null && hit.entityHit != null){

			if(AllyDesignationSystem.isValidTarget(getThrower(), hit.entityHit)){

				Vec3d direction = new Vec3d(hit.entityHit.posX, hit.entityHit.posY + hit.entityHit.height/2,
						hit.entityHit.posZ).subtract(this.getPositionVector()).normalize().scale(velocity.length());

				motionX = motionX + 2 * (direction.x - motionX) / SEEKING_TIME;
				motionY = motionY + 2 * (direction.y - motionY) / SEEKING_TIME;
				motionZ = motionZ + 2 * (direction.z - motionZ) / SEEKING_TIME;
			}
		}
	}
}
